Range over Iterators & func (Go 1.23+):
package main

// Backwards iterates over a slice in reverse
func Backwards[E any](s []E) func(func(int, E) bool) {
	return func(yield func(int, E) bool) {
		for i := len(s) - 1; i >= 0; i-- {
			if !yield(i, s[i]) {
				return
			}
		}
	}
}

func main() {
	s := []string{"a", "b", "c"}
	for i, v := range Backwards(s) {
		fmt.Println(i, v)  // 2 c, 1 b, 0 a
	}
}

