// Race example (detect with: go run -race .)
var counter int
var wg sync.WaitGroup
for i := 0; i < 1000; i++ {
	wg.Add(1)
	go func() {
		defer wg.Done()
		counter++  // RACE: unsynchronized write
	}()
}
wg.Wait()

// Fix: use atomic or mutex
var atomicCounter atomic.Int64
for i := 0; i < 1000; i++ {
	wg.Add(1)
	go func() {
		defer wg.Done()
		atomicCounter.Add(1)  // safe
	}()
}

